class LRUCache
  def initialize(capacity)
    raise ArgumentError, "capacity must be a non-negative integer" unless capacity.is_a?(Integer) && capacity >= 0

    @capacity = capacity
    @entries = {}
  end

  # Returns the value for key, or nil if the key is not cached.
  # Accessing a key makes it the most recently used entry.
  def get(key)
    return nil unless @entries.key?(key)

    value = @entries.delete(key)
    @entries[key] = value
    value
  end

  # Adds or updates a key/value pair, evicting the least recently used entry
  # when the cache is full.
  def put(key, value)
    return if @capacity.zero?

    @entries.delete(key)
    @entries[key] = value
    @entries.shift if @entries.size > @capacity
  end
end
